<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { ArrowUpRight, ArrowRight, Check, ChevronRight, Circle, Database, HardDrive, Cpu, RefreshCw, ShieldCheck, Globe, Server, ExternalLink, Clock3, LockKeyhole, Plus, Search, CheckCircle2, AlertCircle, Monitor, Palette, Users, Leaf, Layers3, FileText, Cloud, FolderOpen, NotebookPen, LogOut, Activity } from 'lucide-vue-next'
import type { AppDefinition, AuditEntry, User } from '../api'
import { api, bytes } from '../api'
import { useDesktop } from '../store'
import AppIcon from './AppIcon.vue'
const props = defineProps<{ app: AppDefinition }>()
const desktop = useDesktop()
const settingsTab = ref('appearance')
const activity = ref<AuditEntry[]>([])
const users = ref<User[]>([])
const loading = ref(false)
const error = ref('')
const filter = ref('')
const showCreate = ref(false)
const newUser = ref({ username: '', displayName: '', password: '', role: 'user' })
const createBusy = ref(false)
const memoryHistory = ref<number[]>([])
const filteredApps = computed(() => desktop.apps.filter(a => a.title.toLocaleLowerCase('vi').includes(filter.value.toLocaleLowerCase('vi'))))
const usedDisk = computed(() => desktop.system ? (1 - desktop.system.diskFreeBytes / Math.max(1, desktop.system.diskTotalBytes)) * 100 : 0)
const clockGreeting = computed(() => { const hour = new Date().getHours(); return hour < 11 ? 'Chào buổi sáng' : hour < 14 ? 'Chào buổi trưa' : hour < 18 ? 'Chào buổi chiều' : 'Chào buổi tối' })
const uptime = computed(() => { const seconds = desktop.system?.uptimeSeconds || 0; return seconds < 60 ? `${seconds} giây` : seconds < 3600 ? `${Math.floor(seconds / 60)} phút` : `${Math.floor(seconds / 3600)} giờ ${Math.floor(seconds % 3600 / 60)} phút` })
const memoryPath = computed(() => { const values = memoryHistory.value; const maximum = Math.max(...values, 1024 ** 2); return values.map((value, i) => `${i ? 'L' : 'M'}${(i / Math.max(1, values.length - 1)) * 260},${64 - value / maximum * 45}`).join(' ') })
const roadmap = [{ version: '0.1', title: 'Desktop đầu tiên', detail: 'Cửa sổ, tài khoản và không gian riêng', current: true }, { version: '0.2', title: 'Kết nối dịch vụ', detail: 'NetBird, Authentik và 1Panel', current: false }, { version: '0.4', title: 'File Station', detail: 'Quản lý và chia sẻ dữ liệu', current: false }, { version: '0.7', title: 'Nền tảng NAS', detail: 'Lưu trữ, agent và dịch vụ file', current: false }]
async function refresh() {
  loading.value = true; error.value = ''
  try {
    if (props.app.id === 'activity') activity.value = await api<AuditEntry[]>('/audit')
    if (props.app.id === 'settings' && desktop.user?.role === 'admin') users.value = await api<User[]>('/admin/users')
    if (['overview', 'about', 'connections'].includes(props.app.id)) await desktop.refreshSystem()
  } catch (e) { error.value = e instanceof Error ? e.message : 'Không tải được dữ liệu.' }
  finally { loading.value = false }
}
async function createUser() {
  createBusy.value = true; error.value = ''
  try { await api('/admin/users', { method: 'POST', body: JSON.stringify(newUser.value) }); newUser.value = { username: '', displayName: '', password: '', role: 'user' }; showCreate.value = false; await refresh(); desktop.toast('Đã tạo tài khoản mới.') }
  catch (e) { error.value = e instanceof Error ? e.message : 'Không tạo được tài khoản.' }
  finally { createBusy.value = false }
}
function setTheme(theme: 'light' | 'dark') { desktop.preferences.theme = theme; desktop.saveSoon() }
function setWallpaper(wallpaper: 'mountain' | 'midnight' | 'sage') { desktop.preferences.wallpaper = wallpaper; desktop.saveSoon() }
function togglePin(id: string) { const pinned = desktop.preferences.pinned; desktop.preferences.pinned = pinned.includes(id) ? pinned.filter(a => a !== id) : [...pinned, id]; desktop.saveSoon() }
function sample() { if (desktop.system) memoryHistory.value = [...memoryHistory.value, desktop.system.heapBytes].slice(-18) }
onMounted(() => { void refresh(); sample() })
const sampler = setInterval(sample, 5000)
onBeforeUnmount(() => clearInterval(sampler))
</script>

<template>
  <div v-if="app.id === 'overview'" class="overview-layout">
    <aside class="app-sidebar">
      <div class="sidebar-caption">KHÔNG GIAN LÀM VIỆC</div>
      <button class="sidebar-item selected"><Monitor :size="17" /> Tổng quan</button>
      <button class="sidebar-item" @click="desktop.open('connections')"><Globe :size="17" /> Kết nối dịch vụ <span class="tiny-count">3</span></button>
      <button class="sidebar-item" @click="desktop.open('activity')"><Clock3 :size="17" /> Nhật ký hoạt động</button>
      <div class="sidebar-caption second">CÁ NHÂN</div>
      <button class="sidebar-item" @click="desktop.open('notes')"><NotebookPen :size="17" /> Ghi chú</button>
      <button class="sidebar-item" @click="desktop.open('settings')"><Palette :size="17" /> Cá nhân hóa</button>
      <div class="sidebar-bottom"><span class="connection-dot"></span><div><strong>Desktop đã sẵn sàng</strong><small>MinhAnOS 0.1.0 · Bản thử nghiệm</small></div></div>
    </aside>
    <main class="overview-main">
      <div class="page-eyebrow"><span>DESKTOP / TỔNG QUAN</span><span class="soft-badge"><span class="connection-dot"></span> Phiên cục bộ</span></div>
      <div class="welcome-heading"><div><p>{{ clockGreeting }}, {{ desktop.user?.displayName }} <span class="greeting-sun">✦</span></p><h1>Mọi thứ, trong tầm tay.</h1><p class="muted">Một không gian riêng. Nhiều điều để khám phá.</p></div><button class="icon-button subtle" aria-label="Làm mới tổng quan" :disabled="loading" @click="refresh"><RefreshCw :size="17" :class="{ spinning: loading }" /></button></div>
      <div class="welcome-banner"><div><span class="eyebrow">CHÀO MỪNG ĐẾN MINHANOS</span><h2>Nhẹ nhàng hơn.<br>Chủ động hơn.</h2><p>Máy chủ, dữ liệu và ứng dụng của bạn,<br>trong một desktop thống nhất.</p><button class="banner-link" @click="desktop.open('apps')">Khám phá không gian mới <ArrowUpRight :size="17" /></button></div><div class="banner-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-stack stack-back"></div><div class="art-stack stack-mid"></div><div class="art-stack stack-front"><Layers3 :size="52" :stroke-width="1.1" /></div><span class="art-star">✧</span><span class="art-dot"></span></div></div>
      <div class="section-label"><h3>Truy cập nhanh</h3><button class="text-button" @click="desktop.open('apps')">Tất cả ứng dụng <ArrowRight :size="14" /></button></div>
      <div class="quick-grid"><button v-for="id in ['files','connections','settings','notes']" :key="id" class="quick-card" @click="desktop.open(id)"><AppIcon :id="id" :color="desktop.apps.find(a => a.id === id)?.color" small /><span>{{ desktop.apps.find(a => a.id === id)?.title }}</span><ChevronRight :size="14" /></button></div>
      <div class="section-label"><h3>Nhịp hoạt động</h3><span class="muted small-text">Dữ liệu thật · Tiến trình & container</span></div>
      <div v-if="desktop.system" class="metric-grid">
        <div class="metric-card"><div class="metric-label"><Cpu :size="15" /> Bộ nhớ ứng dụng <span class="connection-dot"></span></div><strong>{{ bytes(desktop.system.heapBytes) }}<span>Go heap</span></strong><svg class="sparkline" viewBox="0 0 260 70" preserveAspectRatio="none" aria-label="Mẫu bộ nhớ tiến trình từ khi mở cửa sổ"><path :d="memoryPath" fill="none" stroke="currentColor" stroke-width="2" /></svg></div>
        <div class="metric-card"><div class="metric-label"><HardDrive :size="15" /> Filesystem /data</div><strong>{{ bytes(desktop.system.diskFreeBytes) }}<span>còn trống</span></strong><div class="storage-track"><i :style="{ width: `${usedDisk}%` }"></i></div><div class="metric-foot">Tổng {{ bytes(desktop.system.diskTotalBytes) }} · {{ usedDisk.toFixed(1) }}% đã dùng</div></div>
        <div class="metric-card"><div class="metric-label"><Database :size="15" /> Nền tảng</div><div class="db-status"><span class="connection-dot" :class="{ offline: desktop.system.database !== 'connected' }"></span> {{ desktop.system.database === 'connected' ? 'Đang hoạt động' : 'Mất kết nối DB' }}</div><div class="metric-foot">PostgreSQL · Go API</div><div class="uptime"><Clock3 :size="13" /> Uptime ứng dụng: {{ uptime }}</div></div>
      </div>
      <div v-else class="inline-error"><AlertCircle :size="17" /> Chưa lấy được trạng thái máy chủ. <button class="text-button" @click="refresh">Thử lại</button></div>
      <div class="overview-footer"><ShieldCheck :size="14" /><span>Bố cục và ghi chú được lưu riêng theo tài khoản.</span><button class="text-button" @click="desktop.open('about')">Về bản thử nghiệm <ArrowUpRight :size="13" /></button></div>
    </main>
  </div>

  <div v-else-if="app.id === 'settings'" class="settings-layout">
    <aside class="app-sidebar"><div class="sidebar-caption">CÀI ĐẶT DESKTOP</div><button class="sidebar-item" :class="{ selected: settingsTab === 'appearance' }" @click="settingsTab = 'appearance'"><Palette :size="17" /> Giao diện</button><button class="sidebar-item" :class="{ selected: settingsTab === 'account' }" @click="settingsTab = 'account'"><ShieldCheck :size="17" /> Tài khoản của tôi</button><button v-if="desktop.user?.role === 'admin'" class="sidebar-item" :class="{ selected: settingsTab === 'users' }" @click="settingsTab = 'users'; refresh()"><Users :size="17" /> Người dùng</button><div class="sidebar-bottom"><span class="connection-dot"></span><small>{{ desktop.saving ? 'Đang lưu…' : desktop.saveError ? 'Chưa lưu được' : 'Tự động lưu thay đổi' }}</small></div></aside>
    <main class="standard-content">
      <template v-if="settingsTab === 'appearance'"><div class="page-eyebrow">CÁ NHÂN HÓA</div><h1>Không gian theo cách bạn.</h1><p class="muted">Những thay đổi nhỏ, cảm giác thân thuộc hơn.</p><section class="workspace-mode-setting"><h3>Cách làm việc</h3><p class="muted small-text">Chọn trải nghiệm phù hợp. Chuyển ứng dụng luôn giữ biểu mẫu đang mở.</p><div class="workspace-mode-options"><button aria-label="Chế độ tập trung" :aria-pressed="desktop.preferences.mode === 'focus'" :class="{chosen:desktop.preferences.mode === 'focus'}" @click="desktop.setMode('focus')"><Monitor :size="24"/><strong>Tập trung</strong><small>Một ứng dụng toàn màn hình · mặc định</small><Check v-if="desktop.preferences.mode === 'focus'" :size="16"/></button><button aria-label="Chế độ cửa sổ" :aria-pressed="desktop.preferences.mode === 'windows'" :class="{chosen:desktop.preferences.mode === 'windows'}" @click="desktop.setMode('windows')"><Layers3 :size="24"/><strong>Cửa sổ</strong><small>Nhiều ứng dụng song song · nâng cao</small><Check v-if="desktop.preferences.mode === 'windows'" :size="16"/></button></div></section><h3 class="settings-section">Chế độ hiển thị</h3><div class="theme-options"><button v-for="theme in (['light','dark'] as const)" :key="theme" class="theme-option" :class="{ chosen: desktop.preferences.theme === theme }" @click="setTheme(theme)"><div :class="['theme-preview',theme]"><span></span><i></i><b></b></div><span>{{ theme === 'light' ? 'Sáng' : 'Tối' }}<Check v-if="desktop.preferences.theme === theme" :size="16" /></span></button></div><h3 class="settings-section">Hình nền desktop</h3><div class="wallpaper-options"><button v-for="wallpaper in (['mountain','midnight','sage'] as const)" :key="wallpaper" class="wallpaper-option" :class="{ chosen: desktop.preferences.wallpaper === wallpaper }" @click="setWallpaper(wallpaper)"><span :class="['wallpaper-preview',wallpaper]"><Check v-if="desktop.preferences.wallpaper === wallpaper" :size="22" /></span><span>{{ {mountain:'Miền tĩnh lặng',midnight:'Đêm phương Bắc',sage:'Vườn xanh'}[wallpaper] }}</span></button></div><div class="info-panel"><Leaf :size="19" /><div><strong>Một desktop, dành riêng cho bạn</strong><p>Theme, hình nền, ghi chú và vị trí cửa sổ được lưu trong tài khoản, kể cả khi bạn đăng nhập lại.</p></div></div><p v-if="desktop.saveError" class="inline-error">{{ desktop.saveError }} <button class="text-button" @click="desktop.persist">Thử lưu lại</button></p></template>
      <template v-else-if="settingsTab === 'account'"><div class="page-eyebrow">DANH TÍNH</div><h1>Tài khoản của tôi</h1><div class="profile-card"><span class="avatar large">{{ desktop.user?.displayName.charAt(0) }}</span><div><h2>{{ desktop.user?.displayName }}</h2><p class="muted">@{{ desktop.user?.username }}</p></div><span class="soft-badge">{{ desktop.user?.role === 'admin' ? 'Quản trị viên' : 'Người dùng' }}</span></div><div class="detail-list"><div><span>Phương thức đăng nhập</span><strong>Tài khoản cục bộ</strong></div><div><span>Phiên làm việc</span><strong>Tối đa 24 giờ</strong></div><div><span>Đăng nhập Authentik</span><strong class="muted">Chưa cấu hình</strong></div><div><span>Múi giờ hiển thị</span><strong>Asia/Bangkok</strong></div></div><div class="info-panel"><ShieldCheck :size="20" /><p>Đây là đăng nhập cục bộ cho bản desktop đầu tiên. SSO Authentik và quản lý mật khẩu sẽ được bổ sung ở mốc tiếp theo.</p></div><button class="secondary-button" @click="desktop.logout().catch(e => desktop.toast(e.message))"><LogOut :size="15" /> Đăng xuất</button></template>
      <template v-else><div class="page-eyebrow">QUẢN TRỊ</div><div class="section-label"><h1>Người dùng</h1><button class="primary-button" @click="showCreate = !showCreate"><Plus :size="16" /> Tạo tài khoản</button></div><p class="muted">Mỗi tài khoản có bố cục và ghi chú độc lập.</p><p v-if="error" class="inline-error" role="alert">{{ error }}</p><form v-if="showCreate" class="create-user-form" @submit.prevent="createUser"><label>Tên hiển thị<input v-model="newUser.displayName" required maxlength="100" placeholder="Nguyễn Minh An"></label><label>Tên đăng nhập<input v-model="newUser.username" required minlength="3" maxlength="32" pattern="[a-z][a-z0-9_-]{2,31}" placeholder="minhan" autocomplete="off"></label><label>Mật khẩu<input v-model="newUser.password" type="password" required minlength="12" maxlength="256" placeholder="Ít nhất 12 ký tự" autocomplete="new-password"></label><label>Vai trò<select v-model="newUser.role"><option value="user">Người dùng</option><option value="admin">Quản trị viên</option></select></label><button class="primary-button" :disabled="createBusy">{{ createBusy ? 'Đang tạo…' : 'Tạo tài khoản' }}</button></form><div class="user-list"><div v-for="user in users" :key="user.id" class="user-row"><span class="avatar">{{ user.displayName.charAt(0) }}</span><div><strong>{{ user.displayName }}</strong><span class="muted">@{{ user.username }}</span></div><span class="soft-badge">{{ user.role === 'admin' ? 'Quản trị viên' : 'Người dùng' }}</span></div></div><p class="small-text muted">Bản 0.1 hỗ trợ tạo tài khoản. Chưa có chức năng sửa, khóa hoặc xóa người dùng.</p></template>
    </main>
  </div>

  <main v-else-if="app.id === 'apps'" class="standard-content">
    <div class="page-eyebrow">APP CENTER / DESKTOP 0.1</div><h1>Mở ra nhiều khả năng.</h1><p class="muted">Các ứng dụng tích hợp trong không gian MinhAnOS.</p><div class="app-search"><Search :size="17" /><input v-model="filter" placeholder="Tìm ứng dụng…" aria-label="Tìm ứng dụng trong trung tâm"></div><div class="catalog-grid"><article v-for="item in filteredApps" :key="item.id" class="catalog-card"><AppIcon :id="item.icon" :color="item.color" /><span class="catalog-status" :class="{ planned: item.status === 'planned' }">{{ item.status === 'ready' ? 'Sẵn sàng' : 'Sắp có' }}</span><h3>{{ item.title }}</h3><p>{{ item.subtitle }}</p><div><button class="text-button" @click="desktop.open(item.id)">Mở ứng dụng <ArrowUpRight :size="14" /></button><button class="pin-button" :aria-label="`${desktop.preferences.pinned.includes(item.id) ? 'Bỏ ghim' : 'Ghim'} ${item.title}`" @click="togglePin(item.id)"><Check v-if="desktop.preferences.pinned.includes(item.id)" :size="15" /><Plus v-else :size="15" /></button></div></article></div><div v-if="!filteredApps.length" class="empty-state"><Search :size="32" /><h3>Không tìm thấy ứng dụng</h3><p>Thử tìm bằng một từ khác.</p></div><p class="muted small-text">Đây là danh mục ứng dụng nội bộ. Cài đặt package bên ngoài chưa được hỗ trợ.</p>
  </main>

  <main v-else-if="app.id === 'connections'" class="standard-content">
    <div class="page-eyebrow">INTEGRATIONS</div><h1>Một nơi. Mọi kết nối.</h1><p class="muted">Nền tảng cho mạng riêng, danh tính và máy chủ của bạn.</p><div class="integration-list"><article v-for="(item,index) in (desktop.system?.integrations || [{id:'netbird',name:'NetBird',description:'Quản lý thiết bị và mạng riêng'},{id:'authentik',name:'Authentik',description:'Đăng nhập tập trung và danh tính'},{id:'onepanel',name:'1Panel',description:'Máy chủ, container và ứng dụng'}])" :key="item.id" class="integration-card"><span :class="['integration-logo', ['blue','amber','teal'][index]]"><component :is="[Globe,ShieldCheck,Server][index]" :size="27" /></span><div><h2>{{ item.name }}</h2><p>{{ item.description }}</p></div><span class="soft-badge neutral"><Circle :size="8" /> Chưa kết nối</span></article></div><div class="info-panel"><LockKeyhole :size="21" /><div><strong>Kết nối thật, trong bước tiếp theo</strong><p>Bản này chưa gọi API của ba dịch vụ. Cần xác minh endpoint, phiên bản và quyền trước khi cấu hình. Không có dữ liệu dịch vụ giả hoặc khóa API lưu ở trình duyệt.</p></div></div><button class="secondary-button" @click="desktop.open('about')">Xem lộ trình phát triển <ArrowRight :size="15" /></button>
  </main>

  <main v-else-if="app.id === 'files'" class="file-station-preview">
    <div class="file-preview-sidebar"><span class="sidebar-caption">VỊ TRÍ</span><span><FolderOpen :size="17" /> Tệp của tôi</span><span><Users :size="17" /> Thư mục chia sẻ</span><span><HardDrive :size="17" /> Lưu trữ</span></div><div class="empty-state file-empty"><div class="large-folder"><FolderOpen :size="60" :stroke-width="1.3" /></div><span class="soft-badge neutral">ĐANG PHÁT TRIỂN</span><h1>Nhà mới cho dữ liệu của bạn.</h1><p>File Station sẽ mang đến thư mục cá nhân, tải lên,<br>chia sẻ và khôi phục trong cùng một desktop.</p><p class="muted small-text">Chưa kết nối volume. Không có file được tạo ở màn hình này.</p><a class="primary-button" href="http://10.1.1.20:8080" target="_blank" rel="noopener noreferrer">Mở bản quản lý file tham chiếu <ExternalLink :size="15" /></a><span class="small-text muted">Bản kodbox riêng · có thể cần đăng nhập lại</span></div>
  </main>

  <main v-else-if="app.id === 'activity'" class="standard-content"><div class="page-eyebrow">ACTIVITY LOG</div><div class="section-label"><h1>Những gì đã diễn ra.</h1><button class="secondary-button" :disabled="loading" @click="refresh"><RefreshCw :size="15" :class="{spinning:loading}" /> Làm mới</button></div><p class="muted">{{ desktop.user?.role === 'admin' ? '60 hoạt động xác thực và quản trị gần nhất.' : 'Hoạt động xác thực của tài khoản bạn.' }}</p><p v-if="error" class="inline-error">{{ error }}</p><div class="audit-list"><div v-for="entry in activity" :key="entry.id" class="audit-row"><span class="audit-icon"><component :is="entry.action === 'user.create' ? Users : ShieldCheck" :size="18" /></span><div><strong>{{ entry.detail }}</strong><p>{{ entry.actor }} <span>· {{ entry.action }}</span></p></div><time>{{ new Date(entry.createdAt).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit'}) }}</time></div></div><div v-if="!activity.length && !loading && !error" class="empty-state"><Activity :size="36" /><h3>Chưa có hoạt động</h3></div></main>

  <main v-else-if="app.id === 'notes'" class="notes-content"><div class="notes-toolbar"><span><NotebookPen :size="16" /> Ghi chú riêng của {{ desktop.user?.displayName }}</span><span :class="{ 'error-text': desktop.saveError }">{{ desktop.saveError ? 'Chưa lưu được' : desktop.saving ? 'Đang lưu…' : 'Tự động lưu' }}</span></div><textarea v-model="desktop.preferences.notes" maxlength="32000" aria-label="Nội dung ghi chú" placeholder="Một ý tưởng mới bắt đầu từ đây…&#10;&#10;Ghi chú này chỉ hiển thị trong tài khoản của bạn." @input="desktop.saveSoon()"></textarea><div class="notes-footer">{{ desktop.preferences.notes.length.toLocaleString('vi-VN') }} / 32.000 ký tự <button v-if="desktop.saveError" class="text-button" @click="desktop.persist">Thử lưu lại</button></div></main>

  <main v-else class="standard-content about-content"><div class="about-brand"><img src="/mark.svg" alt="" width="64" height="64"><span>MinhAn<span>OS</span></span></div><span class="soft-badge">DESKTOP PREVIEW · 0.1.0</span><h1>Không gian riêng.<br>Khả năng rộng mở.</h1><p class="muted">Được xây mới bằng Vue, TypeScript và Go.<br>Từng bước hướng đến nền tảng quản trị máy chủ và NAS.</p><div class="roadmap"><div v-for="step in roadmap" :key="step.version" :class="{current:step.current}"><span>{{ step.version }}</span><div><strong>{{ step.title }}</strong><p>{{ step.detail }}</p></div><CheckCircle2 v-if="step.current" :size="19" /></div></div><div v-if="desktop.system" class="detail-list compact"><div><span>Backend</span><strong>{{ desktop.system.goVersion }} · {{ desktop.system.architecture }}</strong></div><div><span>Database</span><strong>PostgreSQL</strong></div><div><span>Node</span><strong>{{ desktop.system.node }}</strong></div><div><span>Phạm vi số liệu</span><strong>Tiến trình & filesystem container</strong></div></div><p class="small-text muted">Bản thử nghiệm chưa có SSO, agent Linux, File Station hay quản lý package. Đây là nền tảng mới, độc lập với bản kodbox đang chạy.</p></main>
</template>
